import math

def prime_factors(n):
    factors = {}
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors[i] = factors.get(i, 0) + 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def is_perfect_cube(factors):
    for exponent in factors.values():
        if exponent % 3 != 0:
            return False
    return True

